def isValid(s: str) -> bool:
    """
    Given a string s containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'  # Use '#' as a default non-parenthesis character.
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
```

